import { useState } from 'react';
import { useNavigate, useSearchParams } from 'react-router-dom';
import { Eye, EyeOff, AlertCircle } from 'lucide-react';
import Logo from '../shared/components/Logo';
import { useTheme } from '../theme/ThemeContext';
import client from '../api/client';
import { useToast } from '../shared/toast/ToastContext';

export default function AdminRegisterPage() {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const { darkMode } = useTheme();
  const { showToast } = useToast();

  const code = searchParams.get('code') || '';
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirm, setShowConfirm] = useState(false);
  const [loading, setLoading] = useState(false);
  const [errors, setErrors] = useState({});

  const [formData, setFormData] = useState({
    code: code,
    email: '',
    telephone: '',
    password: '',
    password_confirm: '',
    first_name: '',
    last_name: '',
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({ ...prev, [name]: value }));
    if (errors[name]) {
      setErrors((prev) => ({ ...prev, [name]: '' }));
    }
  };

  const validateForm = () => {
    const newErrors = {};

    if (!formData.code.trim()) newErrors.code = 'Code d\'invitation requis';
    if (!formData.first_name.trim()) newErrors.first_name = 'Prénom requis';
    if (!formData.last_name.trim()) newErrors.last_name = 'Nom requis';
    if (!formData.email.trim()) newErrors.email = 'Email requis';
    else if (!formData.email.includes('@')) newErrors.email = 'Email invalide';
    if (!formData.telephone.trim()) newErrors.telephone = 'Numéro de téléphone requis';
    if (!formData.password) newErrors.password = 'Mot de passe requis';
    if (formData.password.length < 8) newErrors.password = 'Min. 8 caractères';
    if (formData.password !== formData.password_confirm) {
      newErrors.password_confirm = 'Les mots de passe ne correspondent pas';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!validateForm()) return;

    setLoading(true);
    try {
      const response = await client.post('/users/admin-register/', {
        code: formData.code,
        email: formData.email,
        password: formData.password,
        first_name: formData.first_name,
        last_name: formData.last_name,
        telephone: formData.telephone,
      });

      showToast('Compte admin créé avec succès !', 'success');

      setTimeout(() => {
        navigate('/login');
      }, 1500);
    } catch (error) {
      const errorData = error.response?.data || {};
      if (typeof errorData === 'object') {
        setErrors(errorData);
      } else {
        showToast(errorData.detail || 'Erreur lors de la création du compte', 'error');
      }
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`min-h-screen flex flex-col items-center justify-center ${darkMode ? 'bg-navy-950' : 'bg-navy-50'} p-4`}>
      <div className="w-full max-w-md">
        <div className="text-center mb-8">
          <Logo size="lg" />
          <p className={`text-sm ${darkMode ? 'text-navy-400' : 'text-navy-600'} mt-2`}>
            Créer un compte administrateur
          </p>
        </div>

        {!code && (
          <div className={`flex items-start gap-3 p-4 rounded-lg mb-6 ${darkMode ? 'bg-red-900/20 border border-red-700' : 'bg-red-50 border border-red-200'}`}>
            <AlertCircle size={20} className="text-red-500 flex-shrink-0 mt-0.5" />
            <div className={`text-sm ${darkMode ? 'text-red-300' : 'text-red-700'}`}>
              Accès réservé. Vous devez posséder un code d'invitation valide.
            </div>
          </div>
        )}

        <form onSubmit={handleSubmit} className="space-y-4">
          <div>
            <label className={`block text-sm font-medium ${darkMode ? 'text-navy-200' : 'text-navy-700'} mb-1`}>
              Code d'invitation
            </label>
            <input
              type="text"
              name="code"
              value={formData.code}
              onChange={handleChange}
              placeholder="Entrez le code d'invitation"
              readOnly={!!code}
              className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'} ${code ? 'opacity-70' : ''}`}
            />
            {errors.code && <p className="text-xs text-red-500">{errors.code}</p>}
          </div>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <input
                type="text"
                name="first_name"
                value={formData.first_name}
                onChange={handleChange}
                placeholder="Prénom"
                className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
              />
              {errors.first_name && <p className="text-xs text-red-500">{errors.first_name}</p>}
            </div>
            <div>
              <input
                type="text"
                name="last_name"
                value={formData.last_name}
                onChange={handleChange}
                placeholder="Nom"
                className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
              />
              {errors.last_name && <p className="text-xs text-red-500">{errors.last_name}</p>}
            </div>
          </div>

          <div>
            <label className={`block text-sm font-medium ${darkMode ? 'text-navy-200' : 'text-navy-700'} mb-1`}>
              Email <span className={`text-xs ${darkMode ? 'text-navy-400' : 'text-navy-500'}`}>(Requis)</span>
            </label>
            <input
              type="email"
              name="email"
              value={formData.email}
              onChange={handleChange}
              placeholder="email@exemple.com"
              className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
            />
            {errors.email && <p className="text-xs text-red-500">{errors.email}</p>}
          </div>

          <div>
            <input
              type="tel"
              name="telephone"
              value={formData.telephone}
              onChange={handleChange}
              placeholder="+221 77 000 00 00"
              className={`w-full px-4 py-2 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
            />
            {errors.telephone && <p className="text-xs text-red-500">{errors.telephone}</p>}
          </div>

          <div className="relative">
            <input
              type={showPassword ? 'text' : 'password'}
              name="password"
              value={formData.password}
              onChange={handleChange}
              placeholder="Mot de passe (min. 8 caractères)"
              className={`w-full px-4 py-2 pr-10 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-2.5"
            >
              <Eye size={18} />
            </button>
            {errors.password && <p className="text-xs text-red-500">{errors.password}</p>}
          </div>

          <div className="relative">
            <input
              type={showConfirm ? 'text' : 'password'}
              name="password_confirm"
              value={formData.password_confirm}
              onChange={handleChange}
              placeholder="Confirmer le mot de passe"
              className={`w-full px-4 py-2 pr-10 rounded-lg border ${darkMode ? 'border-navy-700 bg-navy-900 text-white' : 'border-navy-200 bg-white'}`}
            />
            <button
              type="button"
              onClick={() => setShowConfirm(!showConfirm)}
              className="absolute right-3 top-2.5"
            >
              <EyeOff size={18} />
            </button>
            {errors.password_confirm && <p className="text-xs text-red-500">{errors.password_confirm}</p>}
          </div>

          <button
            type="submit"
            disabled={loading}
            className="w-full bg-navy dark:bg-navy-800 text-white py-3 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-900 transition disabled:opacity-50"
          >
            {loading ? 'Création...' : 'Créer un compte admin'}
          </button>
        </form>
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { ArrowLeft, CheckCircle } from 'lucide-react';
import Logo from '../shared/components/Logo';
import { useTheme } from '../theme/ThemeContext';
import client from '../api/client';
import { useToast } from '../shared/toast/ToastContext';

export default function ForgotPasswordPage() {
  const navigate = useNavigate();
  const { darkMode } = useTheme();
  const { showToast } = useToast();

  const [userType, setUserType] = useState('citoyen'); // citoyen ou autorite
  const [step, setStep] = useState(1); // 1: input, 2: success
  const [contact, setContact] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const isCitoyen = userType === 'citoyen';
  const contactLabel = isCitoyen ? 'Numéro de téléphone' : 'Email';
  const placeholder = isCitoyen ? '+221 77 000 00 00' : 'email@exemple.com';
  const inputType = isCitoyen ? 'tel' : 'email';

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError('');

    if (!contact.trim()) {
      setError(`${contactLabel} requis`);
      return;
    }

    if (!isCitoyen && !contact.includes('@')) {
      setError('Email invalide');
      return;
    }

    setLoading(true);
    try {
      const payload = isCitoyen
        ? { telephone: contact }
        : { email: contact };

      await client.post('/users/password-reset/', payload);
      setStep(2);
      showToast('Instructions de réinitialisation envoyées', 'success');
    } catch (err) {
      setError(err.response?.data?.detail || 'Erreur lors de l\'envoi des instructions');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`min-h-screen flex flex-col items-center justify-center ${darkMode ? 'bg-navy-950' : 'bg-navy-50'} p-4`}>
      <div className="w-full max-w-md">
        <button
          onClick={() => navigate('/login')}
          className={`flex items-center gap-2 mb-8 ${darkMode ? 'text-navy-400 hover:text-navy-200' : 'text-navy-600 hover:text-navy-900'} transition`}
        >
          <ArrowLeft size={18} />
          Retour
        </button>

        <div className="text-center mb-8">
          <Logo size="lg" />
          <h1 className={`text-2xl font-bold mt-4 ${darkMode ? 'text-white' : 'text-navy-900'}`}>
            {step === 1 ? 'Mot de passe oublié ?' : isCitoyen ? 'SMS envoyé' : 'Email envoyé'}
          </h1>
        </div>

        {step === 1 ? (
          <>
            {/* Onglets Citoyen/Autorité */}
            <div className="flex bg-navy-50 dark:bg-navy-800 rounded-md p-1 mb-6">
              {['citoyen', 'autorite'].map((type) => (
                <button
                  key={type}
                  onClick={() => {
                    setUserType(type);
                    setContact('');
                    setError('');
                  }}
                  className={`flex-1 text-center py-2 rounded-md text-sm transition-colors ${
                    userType === type
                      ? 'bg-white dark:bg-navy text-navy dark:text-navy-50 font-bold shadow'
                      : 'text-navy-600 dark:text-navy-200 font-semibold'
                  }`}
                >
                  {type === 'citoyen' ? 'Citoyen' : 'Autorité'}
                </button>
              ))}
            </div>

            <form onSubmit={handleSubmit} className="space-y-4">
              <p className={`text-sm ${darkMode ? 'text-navy-300' : 'text-navy-700'} mb-6`}>
                Entrez votre {contactLabel.toLowerCase()} pour recevoir les instructions de réinitialisation.
              </p>

              <div>
                <label className={`block text-sm font-medium ${darkMode ? 'text-navy-200' : 'text-navy-700'} mb-1`}>
                  {contactLabel}
                </label>
                <input
                  type={inputType}
                  value={contact}
                  onChange={(e) => {
                    setContact(e.target.value);
                    setError('');
                  }}
                  placeholder={placeholder}
                  className={`w-full px-4 py-2 rounded-lg border ${
                    error
                      ? 'border-red-500'
                      : darkMode
                        ? 'border-navy-700 bg-navy-900 text-white'
                        : 'border-navy-200 bg-white'
                  } focus:outline-none focus:ring-2 focus:ring-navy-500`}
                />
                {error && <p className="text-xs text-red-500 mt-1">{error}</p>}
              </div>

              <button
                type="submit"
                disabled={loading}
                className="w-full bg-navy dark:bg-navy-800 text-white py-3 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-900 transition disabled:opacity-50"
              >
                {loading ? 'Envoi...' : 'Envoyer les instructions'}
              </button>
            </form>
          </>
        ) : (
          <div className="text-center py-8">
            <CheckCircle size={64} className="text-green-500 mx-auto mb-4" />
            <p className={`text-sm ${darkMode ? 'text-navy-300' : 'text-navy-700'} mb-6`}>
              {isCitoyen
                ? `Un SMS avec les instructions de réinitialisation a été envoyé à ${contact}`
                : `Un email avec les instructions de réinitialisation a été envoyé à ${contact}`}
            </p>
            <p className={`text-xs ${darkMode ? 'text-navy-400' : 'text-navy-600'} mb-8`}>
              {isCitoyen
                ? 'Vérifiez vos messages SMS dans quelques minutes.'
                : 'Vérifiez votre boîte mail (et les spams) dans quelques minutes.'}
            </p>
            <button
              onClick={() => navigate('/login')}
              className="w-full bg-navy dark:bg-navy-800 text-white py-3 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-900 transition"
            >
              Retour à la connexion
            </button>
          </div>
        )}
      </div>
    </div>
  );
}

import { useState } from 'react';
import { useNavigate, useLocation } from 'react-router-dom';
import { ArrowLeft, CheckCircle, Clock } from 'lucide-react';
import Logo from '../shared/components/Logo';
import { useTheme } from '../theme/ThemeContext';
import { useAuth } from '../auth/AuthContext';
import client from '../api/client';
import { useToast } from '../shared/toast/ToastContext';

export default function OTPVerificationPage() {
  const navigate = useNavigate();
  const location = useLocation();
  const { darkMode } = useTheme();
  const { login } = useAuth();
  const { showToast } = useToast();

  const email = location.state?.email || '';
  const phoneNumber = location.state?.phoneNumber || '';
  const username = location.state?.username || '';

  const [step, setStep] = useState(1); // 1: OTP input, 2: success
  const [otp, setOtp] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [resendTimer, setResendTimer] = useState(0);

  if (!username) {
    return (
      <div className={`min-h-screen flex flex-col items-center justify-center ${darkMode ? 'bg-navy-950' : 'bg-navy-50'} p-4`}>
        <div className="w-full max-w-md text-center">
          <p className={`text-lg font-semibold ${darkMode ? 'text-white' : 'text-navy-900'}`}>
            Erreur : données manquantes
          </p>
          <button
            onClick={() => navigate('/signup')}
            className="mt-4 text-navy-600 dark:text-navy-400 hover:underline"
          >
            Retour à l'inscription
          </button>
        </div>
      </div>
    );
  }

  const handleSubmitOTP = async (e) => {
    e.preventDefault();
    setError('');

    if (!otp.trim()) {
      setError('Code OTP requis');
      return;
    }

    if (otp.length < 6) {
      setError('Le code OTP doit avoir au moins 6 caractères');
      return;
    }

    setLoading(true);
    try {
      const response = await client.post('/users/verify-otp/', {
        username,
        otp,
      });

      showToast('Vérification réussie ! Connexion en cours...', 'success');
      setStep(2);

      // Auto-login après 1.5 secondes
      await new Promise((resolve) => setTimeout(resolve, 1500));

      // Connexion automatique
      try {
        await login({ username, password: location.state?.password || '' });
        navigate('/citoyen/accueil', { replace: true });
      } catch {
        // Si auto-login échoue, rediriger vers login
        navigate('/login', { state: { tab: 'citoyen' }, replace: true });
      }
    } catch (err) {
      setError(err.response?.data?.detail || 'Code OTP invalide');
    } finally {
      setLoading(false);
    }
  };

  const handleResend = async () => {
    setError('');
    setLoading(true);
    try {
      await client.post('/users/resend-otp/', { username });
      showToast('Code OTP renvoyé', 'success');
      setResendTimer(60);

      // Countdown timer
      const interval = setInterval(() => {
        setResendTimer((prev) => {
          if (prev <= 1) {
            clearInterval(interval);
            return 0;
          }
          return prev - 1;
        });
      }, 1000);
    } catch (err) {
      setError(err.response?.data?.detail || 'Erreur lors de l\'envoi du code');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={`min-h-screen flex flex-col items-center justify-center ${darkMode ? 'bg-navy-950' : 'bg-navy-50'} p-4`}>
      <div className="w-full max-w-md">
        <button
          onClick={() => navigate('/signup')}
          className={`flex items-center gap-2 mb-8 ${darkMode ? 'text-navy-400 hover:text-navy-200' : 'text-navy-600 hover:text-navy-900'} transition`}
        >
          <ArrowLeft size={18} />
          Retour
        </button>

        <div className="text-center mb-8">
          <Logo size="lg" />
          <h1 className={`text-2xl font-bold mt-4 ${darkMode ? 'text-white' : 'text-navy-900'}`}>
            {step === 1 ? 'Vérifier votre identité' : 'Vérification réussie'}
          </h1>
        </div>

        {step === 1 ? (
          <form onSubmit={handleSubmitOTP} className="space-y-4">
            <div className="bg-blue-50 dark:bg-blue-950 border border-blue-200 dark:border-blue-800 rounded-lg p-4 mb-6">
              <div className="flex gap-2">
                <Clock size={20} className="text-blue-600 dark:text-blue-400 flex-shrink-0" />
                <div>
                  <p className={`text-sm font-medium ${darkMode ? 'text-blue-400' : 'text-blue-900'}`}>
                    Code OTP envoyé
                  </p>
                  <p className={`text-xs ${darkMode ? 'text-blue-300' : 'text-blue-700'} mt-1`}>
                    {email ? `Email: ${email}` : `Téléphone: ${phoneNumber}`}
                  </p>
                </div>
              </div>
            </div>

            <div>
              <label className={`block text-sm font-medium ${darkMode ? 'text-navy-200' : 'text-navy-700'} mb-2`}>
                Code OTP (6 chiffres minimum)
              </label>
              <input
                type="text"
                value={otp}
                onChange={(e) => {
                  setOtp(e.target.value);
                  setError('');
                }}
                placeholder="000000"
                maxLength="8"
                className={`w-full px-4 py-3 rounded-lg border text-center text-2xl tracking-widest font-mono ${
                  error
                    ? 'border-red-500'
                    : darkMode
                      ? 'border-navy-700 bg-navy-900 text-white'
                      : 'border-navy-200 bg-white'
                } focus:outline-none focus:ring-2 focus:ring-navy-500`}
              />
              {error && <p className="text-xs text-red-500 mt-2">{error}</p>}
            </div>

            <button
              type="submit"
              disabled={loading}
              className="w-full bg-navy dark:bg-navy-800 text-white py-3 rounded-lg font-semibold hover:bg-navy-700 dark:hover:bg-navy-900 transition disabled:opacity-50"
            >
              {loading ? 'Vérification...' : 'Vérifier le code'}
            </button>

            <div className="text-center pt-4">
              <p className={`text-sm ${darkMode ? 'text-navy-400' : 'text-navy-600'}`}>
                Vous n'avez pas reçu le code ?
              </p>
              <button
                type="button"
                onClick={handleResend}
                disabled={resendTimer > 0 || loading}
                className={`text-sm font-semibold mt-2 ${
                  resendTimer > 0
                    ? `${darkMode ? 'text-navy-600' : 'text-navy-400'} cursor-not-allowed`
                    : `text-navy-600 dark:text-navy-400 hover:underline`
                }`}
              >
                {resendTimer > 0 ? `Renvoyer dans ${resendTimer}s` : 'Renvoyer le code'}
              </button>
            </div>
          </form>
        ) : (
          <div className="text-center py-8">
            <CheckCircle size={64} className="text-green-500 mx-auto mb-4" />
            <p className={`text-lg font-semibold ${darkMode ? 'text-white' : 'text-navy-900'} mb-2`}>
              Vérification réussie !
            </p>
            <p className={`text-sm ${darkMode ? 'text-navy-300' : 'text-navy-700'} mb-6`}>
              Vous pouvez maintenant accéder à votre compte citoyen.
            </p>
            <p className={`text-xs ${darkMode ? 'text-navy-400' : 'text-navy-600'}`}>
              Redirection en cours vers le tableau de bord...
            </p>
          </div>
        )}
      </div>
    </div>
  );
}

import { Link } from 'react-router-dom';
import Logo from '../shared/components/Logo';
import ThemeToggle from '../theme/ThemeToggle';

// Pas encore de endpoint d'auto-inscription côté backend (hors des trois
// lacunes comblées en Phase 0) — cet écran reprend la maquette validée mais
// reste volontairement non fonctionnel tant que ce endpoint n'existe pas.
export default function SignupPage() {
  return (
    <div className="min-h-screen flex items-center justify-center px-6 py-12 bg-navy-50 dark:bg-navy-950 relative">
      <ThemeToggle className="absolute top-7 right-8" />
      <div className="w-full max-w-[420px] lg:max-w-[480px]">
        <div className="flex flex-col items-center mb-7 lg:mb-9">
          <Logo size="lg" className="lg:scale-125 lg:mb-2" withSlogan />
        </div>

        <div className="bg-white dark:bg-navy rounded-xl border border-navy-50 dark:border-navy-800 shadow-lg p-7 lg:p-9">
          <h1 className="text-base font-extrabold text-navy dark:text-navy-50 mb-4">Créer un compte citoyen</h1>

          <div className="px-3.5 py-3 rounded-md bg-navy-50 dark:bg-navy-800 text-navy-600 dark:text-navy-200 text-xs mb-5">
            L'auto-inscription n'est pas encore disponible — contactez la mairie de Thiaroye-sur-Mer ou une autorité
            habilitée pour obtenir un accès citoyen.
          </div>

          <p className="text-center text-xs text-navy-600 dark:text-navy-200">
            Déjà inscrit ?{' '}
            <Link to="/login" className="font-bold text-red">
              Se connecter
            </Link>
          </p>
        </div>
      </div>
    </div>
  );
}

