                  `flex items-center gap-2.5 px-4 py-2.5 text-sm font-semibold transition-colors ${
                    isActive
                      ? 'bg-navy dark:bg-navy-800 text-white'
                      : 'text-navy-600 dark:text-navy-200 hover:bg-navy-50 dark:hover:bg-navy-800'
                  }`
                }
              >
                <TrendingUp size={14} />
                Suivi des autorités
              </NavLink>
              <NavLink
                to="/autorite/authorities"
                onClick={() => setOpen(false)}
                className={({ isActive }) =>
                  `flex items-center gap-2.5 px-4 py-2.5 text-sm font-semibold transition-colors ${
                    isActive
                      ? 'bg-navy dark:bg-navy-800 text-white'
                      : 'text-navy-600 dark:text-navy-200 hover:bg-navy-50 dark:hover:bg-navy-800'
                  }`
                }
              >
                <UserPlus size={14} />
                Gérer les autorités
              </NavLink>
            </>
          )}
          <button
            onClick={() => {
              setOpen(false);
              logout();
            }}
            className="w-full flex items-center gap-2.5 px-4 py-2.5 text-sm font-semibold text-red hover:bg-red-50 dark:hover:bg-red/10 transition-colors text-left border-t border-navy-50 dark:border-navy-800"
          >
            <PhoneCall size={14} />
            Se déconnecter
          </button>
        </div>
      )}
    </div>
  );
}

export default function AutoriteShell({ children }) {
  const { logout, role } = useAuth();
  const isAdmin = role === 'admin';
  const [moreOpen, setMoreOpen] = useState(false);
  const moreRef = useRef(null);

  // Sélectionner les items selon le rôle
  const toolsItems = isAdmin ? [...TOOLS_ITEMS_COMMON, ...TOOLS_ITEMS_ADMIN] : TOOLS_ITEMS_COMMON;

  useEffect(() => {
    function handleClickOutside(e) {
      if (moreRef.current && !moreRef.current.contains(e.target)) {
        setMoreOpen(false);
      }
    }
    if (moreOpen) document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [moreOpen]);

  return (
    <div className="min-h-screen bg-navy-50 dark:bg-navy-950 text-navy dark:text-navy-50 flex flex-col">
      <div className="bg-white dark:bg-navy border-b border-navy-50 dark:border-navy-800 flex-shrink-0">
        <div className="max-w-[1600px] mx-auto flex items-center justify-between px-7 py-4">
          <Logo size="sm" />
          <div className="flex items-center gap-2">
            <DropdownMenu label="Outils" icon={BarChart3} items={toolsItems} />
            <NotificationCenter />
            <ThemeToggle />
            <ProfileMenu isAdmin={isAdmin} logout={logout} />
          </div>
        </div>
      </div>

      <div className="flex-1 max-w-[1600px] w-full mx-auto flex gap-6 px-7 py-6 items-start">
        <nav className="w-60 flex-shrink-0 flex flex-col gap-1 sticky top-6">
          {SIDEBAR_ITEMS.map(({ to, label, icon: Icon }) => (
            <NavLink
              key={to}
              to={to}
              className={({ isActive }) =>
                `flex items-center gap-2.5 px-3.5 py-2.5 rounded-md text-lg font-semibold transition-colors ${
                  isActive
                    ? 'bg-navy dark:bg-navy-800 text-white'
                    : 'text-navy-600 dark:text-navy-200 hover:bg-navy-50 dark:hover:bg-navy-800'
                }`
              }
            >
              <Icon size={18} />
              {label}
            </NavLink>
          ))}

          <div ref={moreRef} className="relative mt-2">
            <button
              onClick={() => setMoreOpen(!moreOpen)}
              className="w-full flex items-center gap-2.5 px-3.5 py-2.5 rounded-md text-base font-semibold text-navy-600 dark:text-navy-200 hover:bg-navy-50 dark:hover:bg-navy-800 transition-colors"
            >
              <MoreVertical size={18} />
              Plus
              <ChevronDown size={16} className={`ml-auto transition-transform ${moreOpen ? 'rotate-180' : ''}`} />
            </button>

            {moreOpen && (
              <div className="absolute top-full left-0 right-0 mt-1 bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-lg shadow-lg z-50">
                {MORE_ITEMS.map(({ to, label, icon: Icon }) => (
                  <NavLink
                    key={to}
                    to={to}
                    onClick={() => setMoreOpen(false)}
                    className={({ isActive }) =>
                      `flex items-center gap-2.5 px-3.5 py-2.5 text-base font-semibold transition-colors ${
                        isActive
                          ? 'bg-navy dark:bg-navy-800 text-white'
                          : 'text-navy-600 dark:text-navy-200 hover:bg-navy-50 dark:hover:bg-navy-800'
                      }`
                    }
                  >
                    <Icon size={16} />
                    {label}
                  </NavLink>
                ))}
              </div>
            )}
          </div>
        </nav>

        <main className="flex-1 min-w-0 flex flex-col gap-5">{children}</main>
      </div>
    </div>
  );
}

import { Gauge, Droplet, CloudRain, Lock } from 'lucide-react';
import AutoriteShell from '../desktop/AutoriteShell';
import { useAuth } from '../../auth/AuthContext';
import { useTheme } from '../../theme/ThemeContext';
import { useCapteurs, useUpdateCapteur } from '../../shared/hooks/useCapteurs';
import { useZones } from '../../shared/hooks/useZones';
import { useMesuresRecentes } from '../../shared/hooks/useMesuresRecentes';

const STATUTS = [
  { value: 'actif', label: 'Actif' },
  { value: 'inactif', label: 'Inactif' },
  { value: 'maintenance', label: 'En maintenance' },
];

const TYPE_LABELS = { eau: 'Capteur eau', pluviometre: 'Pluviomètre' };

const STATUT_DOT = {
  actif: 'bg-risk-vert',
  inactif: 'bg-navy-400',
  maintenance: 'bg-risk-orange',
};

function formatDateTime(iso) {
  if (!iso) return 'Jamais';
  return new Date(iso).toLocaleString('fr-FR', { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' });
}

export default function AdminCapteursPage() {
  const { role } = useAuth();
  const { darkMode } = useTheme();
  const { data: capteursData, isLoading } = useCapteurs();
  const { data: zonesData } = useZones();
  const { data: mesuresRecentes } = useMesuresRecentes();

  // Vérifier que l'utilisateur est admin
  if (role !== 'admin') {
    return (
      <AutoriteShell>
        <div className="flex items-center justify-center min-h-screen">
          <div className={`text-center ${darkMode ? 'bg-navy' : 'bg-white'} p-12 rounded-xl border ${darkMode ? 'border-navy-800' : 'border-navy-50'}`}>
            <Lock size={48} className="mx-auto mb-4 text-red-500" />
            <h2 className="text-2xl font-bold text-navy dark:text-white mb-2">Accès réservé aux administrateurs</h2>
            <p className="text-navy-600 dark:text-navy-300">Cette page n'est accessible que pour les administrateurs du système.</p>
          </div>
        </div>
      </AutoriteShell>
    );
  }
  const updateCapteur = useUpdateCapteur();

  const zoneNameById = new Map((zonesData?.features ?? []).map((f) => [f.id, f.properties.quartier]));
  const releveCountByCapteur = new Map((mesuresRecentes ?? []).map((g) => [g.capteur.id, g.mesures.length]));

  const capteurs = capteursData?.features ?? [];
  const actifs = capteurs.filter((f) => f.properties.statut === 'actif').length;

  return (
    <AutoriteShell>
      <div>
        <h1 className="text-3xl font-extrabold">Admin & capteurs</h1>
        <p className="text-base text-navy-600 dark:text-navy-200 mt-0.5">
          {capteurs.length} capteur{capteurs.length > 1 ? 's' : ''} enregistré{capteurs.length > 1 ? 's' : ''} ·{' '}
          {actifs} actif{actifs > 1 ? 's' : ''}
        </p>
      </div>

      <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5 flex flex-col gap-3">
        {isLoading ? (
          <p className="text-sm text-navy-400">Chargement…</p>
        ) : capteurs.length === 0 ? (
          <p className="text-sm text-navy-400">Aucun capteur enregistré pour l’instant.</p>
        ) : (
          capteurs.map((f) => (
            <div key={f.id} className="flex items-center gap-3 p-3.5 border border-navy-50 dark:border-navy-800 rounded-lg">
              <div className="w-10 h-10 rounded-lg bg-navy-50 dark:bg-navy-800 flex items-center justify-center flex-shrink-0 text-navy dark:text-navy-50">
                {f.properties.type === 'pluviometre' ? <CloudRain size={17} /> : <Droplet size={17} />}
              </div>

              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2">
                  <span className={`w-2 h-2 rounded-full flex-shrink-0 ${STATUT_DOT[f.properties.statut] ?? 'bg-navy-400'}`} />
                  <span className="text-base font-semibold truncate">{f.properties.nom}</span>
                </div>
                <p className="text-sm text-navy-400 mt-0.5">
                  {TYPE_LABELS[f.properties.type] ?? f.properties.type} ·{' '}
                  {zoneNameById.get(f.properties.zone) ?? 'Zone non assignée'} · Dernier relevé :{' '}
                  {formatDateTime(f.properties.dernier_releve)}
                  {releveCountByCapteur.has(f.id) && ` · ${releveCountByCapteur.get(f.id)} relevé(s) sur 24h`}
                </p>
              </div>

              <select
                value={f.properties.statut}
                onChange={(e) => updateCapteur.mutate({ id: f.id, payload: { statut: e.target.value } })}
                disabled={updateCapteur.isPending}
                className="text-sm font-semibold px-2.5 py-2 rounded-md border-[1.5px] border-navy-200 dark:border-navy-800 bg-white dark:bg-navy flex-shrink-0"
              >
                {STATUTS.map((s) => (
                  <option key={s.value} value={s.value}>
                    {s.label}
                  </option>
                ))}
              </select>
            </div>
          ))
        )}
      </div>

      <div className="bg-white dark:bg-navy border border-navy-50 dark:border-navy-800 rounded-xl p-5">
        <h3 className="text-base font-bold mb-3 flex items-center gap-2">
          <Gauge size={15} />
          Relevés des dernières 24h
        </h3>
        {!mesuresRecentes || mesuresRecentes.length === 0 ? (
          <p className="text-sm text-navy-400">Aucun relevé enregistré sur les dernières 24h.</p>
        ) : (
          <div className="flex flex-col gap-2">
            {mesuresRecentes.map((g) => (
              <div key={g.capteur.id} className="flex items-center justify-between text-sm border-b border-navy-50 dark:border-navy-800 pb-2 last:border-0 last:pb-0">
                <span className="font-semibold">{g.capteur.properties.nom}</span>
                <span className="text-navy-400">
                  {g.mesures.length} mesure{g.mesures.length > 1 ? 's' : ''} · dernière :{' '}
                  {g.mesures[0]?.valeur} {g.mesures[0]?.unite}
                </span>
              </div>
            ))}
          </div>
        )}
      </div>
    </AutoriteShell>
  );
}

import { useState, useEffect } from 'react';
import { useTheme } from '../../theme/ThemeContext';
import { useAuth } from '../../auth/AuthContext';
import { useToast } from '../../shared/toast/ToastContext';
import AutoriteShell from '../desktop/AutoriteShell';
import client from '../../api/client';
import { Users, Search, ChevronRight, X, AlertCircle, Inbox, Bell, Clock, TrendingUp, Eye } from 'lucide-react';

function AuthorityTrackingContent() {
  const { darkMode } = useTheme();
  const { role } = useAuth();
  const { showToast } = useToast();
  const [authorities, setAuthorities] = useState([]);
  const [totalStats, setTotalStats] = useState({});
  const [loading, setLoading] = useState(true);
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedAuthority, setSelectedAuthority] = useState(null);

  useEffect(() => {
    if (role !== 'admin') return;

    const fetchStats = async () => {
      try {
        const response = await client.get('/users/authority-stats/');
        setAuthorities(response.data.authorities || []);
        setTotalStats(response.data.total_stats || {});
      } catch (error) {
        if (import.meta.env.DEV) console.error('Erreur récupération stats:', error);
        showToast('Erreur lors du chargement des statistiques', 'error');
      } finally {
        setLoading(false);
      }
    };

    fetchStats();
  }, [role, showToast]);

  const filteredAuthorities = authorities.filter((auth) => {
    const query = searchQuery.toLowerCase();
    return (
      auth.first_name.toLowerCase().includes(query) ||
      auth.last_name.toLowerCase().includes(query) ||
      auth.username.toLowerCase().includes(query) ||
      auth.email.toLowerCase().includes(query)
    );
  });

  if (role !== 'admin') {
    return (
      <div className="flex items-center justify-center min-h-screen">
        <div className="text-center">
          <h2 className="text-2xl font-bold text-navy dark:text-white">Accès réservé</h2>
          <p className="text-navy-600 dark:text-navy-300">Seuls les administrateurs peuvent voir cette page.</p>
        </div>
      </div>
    );
  }

  const bgCard = darkMode ? 'bg-navy' : 'bg-white';
  const borderCard = darkMode ? 'border-navy-800' : 'border-navy-50';
  const bgTable = darkMode ? 'bg-navy-900' : 'bg-white';
  const hoverRow = darkMode ? 'hover:bg-navy-800/50' : 'hover:bg-navy-50/50';

  return (
    <div className="space-y-6">
      {/* En-tête */}
      <div>
        <h1 className="text-3xl font-bold text-navy dark:text-white flex items-center gap-3">
          <Users size={32} className="text-red" />
          Suivi des Autorités
        </h1>
        <p className="text-sm text-navy-600 dark:text-navy-200 mt-1">
          Aperçu du travail et des performances de vos équipes
        </p>
      </div>

      {/* Statistiques Globales */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-4">
        <StatCard
          icon={AlertCircle}
          title="Crises Gérées"
          value={totalStats.crises_gerees || 0}
          color="from-red-500 to-red-600"
        />
        <StatCard
          icon={Inbox}
          title="Requêtes Traitées"
          value={totalStats.requetes_traitees || 0}
          color="from-blue-500 to-blue-600"
        />
        <StatCard
          icon={Bell}
          title="Alertes Envoyées"
          value={totalStats.alertes_envoyees || 0}
          color="from-orange-500 to-orange-600"
        />
        <StatCard
          icon={Clock}
          title="Heures Travail"
          value={Math.round(totalStats.heures_travail_total || 0)}
          suffix="h"
          color="from-green-500 to-green-600"
        />
      </div>

      {/* Recherche + Tableau */}
      <div className={`${bgTable} border ${borderCard} rounded-xl overflow-hidden`}>
        {/* Barre de recherche */}
        <div className="p-6 border-b border-navy-200 dark:border-navy-800">
          <div className="relative">
            <Search className="absolute left-3 top-3.5 text-navy-400 dark:text-navy-500" size={20} />
            <input
              type="text"
              placeholder="Rechercher par nom, email ou identifiant..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-3 rounded-lg border border-navy-200 dark:border-navy-700 bg-white dark:bg-navy-800 text-navy dark:text-white text-sm"
            />
          </div>
          <p className="text-xs text-navy-600 dark:text-navy-400 mt-2">
            {filteredAuthorities.length} / {authorities.length} autorités trouvées
          </p>
        </div>

        {/* Tableau */}
        {loading ? (
          <div className="flex items-center justify-center p-8">
            <div className="text-center">
              <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-red mx-auto mb-2"></div>
              <p className="text-navy-600 dark:text-navy-300">Chargement...</p>
            </div>
          </div>
        ) : filteredAuthorities.length === 0 ? (
          <div className="p-12 text-center text-navy-600 dark:text-navy-300">
            Aucune autorité trouvée
          </div>
        ) : (
          <div className="overflow-x-auto">
            <table className="w-full text-sm">
              <thead>
                <tr className="border-b border-navy-200 dark:border-navy-800 bg-navy-50 dark:bg-navy-800">
                  <th className="px-6 py-4 text-left font-semibold text-navy-700 dark:text-navy-200">Nom</th>
                  <th className="px-6 py-4 text-left font-semibold text-navy-700 dark:text-navy-200">Email</th>
                  <th className="px-6 py-4 text-center font-semibold text-navy-700 dark:text-navy-200">Crises</th>
                  <th className="px-6 py-4 text-center font-semibold text-navy-700 dark:text-navy-200">Requêtes</th>
                  <th className="px-6 py-4 text-center font-semibold text-navy-700 dark:text-navy-200">Alertes</th>
                  <th className="px-6 py-4 text-center font-semibold text-navy-700 dark:text-navy-200">Heures</th>
                  <th className="px-6 py-4 text-center font-semibold text-navy-700 dark:text-navy-200">Activité</th>
                  <th className="px-6 py-4 text-center font-semibold text-navy-700 dark:text-navy-200">Action</th>
                </tr>
              </thead>
              <tbody>
                {filteredAuthorities.map((auth) => (
                  <tr key={auth.id} className={`border-b border-navy-200 dark:border-navy-800 ${hoverRow} transition-colors cursor-pointer`}>
                    <td className="px-6 py-4">
                      <div>
                        <p className="font-semibold text-navy dark:text-white">
                          {auth.first_name} {auth.last_name}
                        </p>
                        <p className="text-xs text-navy-600 dark:text-navy-400 mt-0.5">{auth.username}</p>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-navy-600 dark:text-navy-300">{auth.email}</td>
                    <td className="px-6 py-4 text-center font-semibold text-navy dark:text-white">{auth.crises_gerees}</td>
                    <td className="px-6 py-4 text-center font-semibold text-navy dark:text-white">{auth.requetes_traitees}</td>
                    <td className="px-6 py-4 text-center font-semibold text-navy dark:text-white">{auth.alertes_envoyees}</td>
                    <td className="px-6 py-4 text-center font-semibold text-navy dark:text-white">{auth.heures_travail.toFixed(1)}h</td>
                    <td className="px-6 py-4 text-center">
                      <div className="flex items-center justify-center gap-1">
                        <div className="h-2 w-24 bg-navy-100 dark:bg-navy-800 rounded-full overflow-hidden">
                          <div
                            className="h-full bg-gradient-to-r from-green-500 to-green-400"
                            style={{ width: `${calculateActivityScore(auth)}%` }}
                          ></div>
                        </div>
                        <span className="text-xs font-bold text-green-600 dark:text-green-400 w-8 text-right">
                          {calculateActivityScore(auth)}%
                        </span>
                      </div>
                    </td>
                    <td className="px-6 py-4 text-center">
                      <button
                        onClick={() => setSelectedAuthority(auth)}
                        className="text-navy-600 dark:text-navy-300 hover:text-navy dark:hover:text-white transition-colors"
                        title="Voir détails"
                      >
                        <Eye size={18} />
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Modal Détails */}
      {selectedAuthority && (
        <AuthorityDetailModal
          authority={selectedAuthority}
          onClose={() => setSelectedAuthority(null)}
          darkMode={darkMode}
        />
      )}
    </div>
  );
}

function StatCard({ icon: Icon, title, value, suffix = '', color }) {
  return (
    <div className={`rounded-xl overflow-hidden shadow-md transition-transform hover:scale-105`}>
      <div className={`bg-gradient-to-br ${color} p-6 text-white`}>
        <div className="flex items-start justify-between mb-3">
          <div>
            <p className="text-sm font-medium opacity-90">{title}</p>
            <p className="text-3xl font-bold mt-1">{value}{suffix}</p>
          </div>
          <Icon size={24} className="opacity-80" />
        </div>
        <div className="h-1 bg-white/20 rounded-full"></div>
      </div>
    </div>
  );
}

function AuthorityDetailModal({ authority, onClose, darkMode }) {
  const [activeTab, setActiveTab] = useState('overview');
  const [activities, setActivities] = useState([]);
  const [activitiesLoading, setActivitiesLoading] = useState(false);
  const { showToast } = useToast();

  useEffect(() => {
    if (activeTab === 'activities') {
      setActivitiesLoading(true);
      client.get(`/users/authority-activities/${authority.id}/`)
        .then(res => setActivities(res.data.activities || []))
        .catch(err => showToast('Erreur lors du chargement des activités', 'error'))
        .finally(() => setActivitiesLoading(false));
    }
  }, [activeTab, authority.id, showToast]);

  const bgModal = darkMode ? 'bg-navy-900' : 'bg-white';
  const borderModal = darkMode ? 'border-navy-800' : 'border-navy-50';
  const bgTabActive = darkMode ? 'bg-navy-800 text-white' : 'bg-navy-50 text-navy';

  return (
    <div className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4 overflow-y-auto">
      <div className={`${bgModal} border ${borderModal} rounded-xl max-w-2xl w-full my-8`}>
        {/* En-tête */}
        <div className="flex items-center justify-between p-6 border-b border-navy-200 dark:border-navy-800">
          <div>
            <h2 className="text-2xl font-bold text-navy dark:text-white">
              {authority.first_name} {authority.last_name}
            </h2>
            <p className="text-sm text-navy-600 dark:text-navy-400 mt-1">{authority.username}</p>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-lg hover:bg-navy-100 dark:hover:bg-navy-800 transition-colors"
          >
            <X size={24} className="text-navy-600 dark:text-navy-300" />
          </button>
        </div>

        {/* Onglets */}
        <div className="flex border-b border-navy-200 dark:border-navy-800">
          {['overview', 'activities'].map((tab) => (
            <button
              key={tab}
              onClick={() => setActiveTab(tab)}
              className={`flex-1 px-6 py-3 font-semibold border-b-2 transition-colors ${
                activeTab === tab
                  ? `${bgTabActive} border-red`
                  : `text-navy-600 dark:text-navy-400 border-transparent hover:bg-navy-50 dark:hover:bg-navy-800/50`
              }`}
            >
              {tab === 'overview' ? 'Vue d\'ensemble' : 'Historique des activités'}
            </button>
          ))}
        </div>

        {/* Contenu */}
        <div className="p-6">
          {activeTab === 'overview' && (
            <div className="space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <DetailStat icon={AlertCircle} label="Crises gérées" value={authority.crises_gerees} />
                <DetailStat icon={Inbox} label="Requêtes traitées" value={authority.requetes_traitees} />
                <DetailStat icon={Bell} label="Alertes envoyées" value={authority.alertes_envoyees} />
                <DetailStat icon={Clock} label="Heures de travail" value={`${authority.heures_travail.toFixed(1)}h`} />
              </div>

              <div className={`p-4 rounded-lg ${darkMode ? 'bg-navy-800' : 'bg-navy-50'}`}>
