        </label>
      </div>

      {saveEmergencyContact.isError && (
        <div className="mt-3 px-3 py-2.5 rounded-md bg-red-50 dark:bg-red/15 text-red-900 dark:text-red-200 text-xs space-y-1">
          {flattenApiErrors(saveEmergencyContact.error).map((msg, i) => (
            <p key={i}>{msg}</p>
          ))}
