                  <p className="text-xs text-navy-600 dark:text-navy-200 mt-0.5">{a.message}</p>
                  <span className="inline-block mt-1 text-[10px] font-bold uppercase text-navy-400">
                    {STATUT_LABELS[a.statut] ?? a.statut}
                  </span>
                </div>
              </div>
            ))}
          </div>
        )}
      </div>
      </div>
    </CitizenShell>
  );
}

