import React, { useState, useEffect } from 'react';
import { LineChart, Line, BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, PieChart, Pie, Cell } from 'recharts';
import './PredictionsDashboard.css';

const COLORS = {
  vert: '#28a745',
  jaune: '#ffc107',
  orange: '#fd7e14',
  rouge: '#dc3545'
};

const LEVEL_LABELS = {
  vert: '🟢 Vert - Risque Faible',
  jaune: '🟡 Jaune - Risque Moyen',
  orange: '🟠 Orange - Risque Élevé',
  rouge: '🔴 Rouge - Risque Critique'
};

export default function PredictionsDashboard() {
  const [zones, setZones] = useState([]);
  const [weatherData, setWeatherData] = useState(null);
  const [historicalData, setHistoricalData] = useState([]);
  const [selectedZone, setSelectedZone] = useState(null);
  const [loading, setLoading] = useState(true);
  const [lastUpdate, setLastUpdate] = useState(null);

  // Récupérer les données toutes les 5 minutes
  useEffect(() => {
    fetchAllData();
    const interval = setInterval(fetchAllData, 5 * 60 * 1000);
    return () => clearInterval(interval);
  }, []);

  const fetchAllData = async () => {
    try {
      setLoading(true);

      // Récupérer zones
      const zonesRes = await fetch('/api/zones-risque/');
      const zonesData = await zonesRes.json();
      setZones(zonesData);

      // Récupérer météo
      const weatherRes = await fetch('/api/previsions-meteo/');
      const weatherDataResponse = await weatherRes.json();
      if (weatherDataResponse.results) {
        setWeatherData(weatherDataResponse.results[0]);
      }

      // Récupérer historique (derniers 7 jours)
      const historicalRes = await fetch('/api/alertes/?limit=30');
      const historicalDataResponse = await historicalRes.json();
      if (historicalDataResponse.results) {
        setHistoricalData(historicalDataResponse.results);
      }

      setLastUpdate(new Date());
    } catch (error) {
      if (import.meta.env.DEV) console.error('Erreur chargement données:', error);
    } finally {
      setLoading(false);
    }
  };

  const getRiskStats = () => {
    const stats = {
      vert: 0,
      jaune: 0,
      orange: 0,
      rouge: 0
    };
    zones.forEach(zone => {
      stats[zone.niveau_risque] = (stats[zone.niveau_risque] || 0) + 1;
    });
    return Object.entries(stats).map(([level, count]) => ({
      name: LEVEL_LABELS[level],
      value: count,
      color: COLORS[level]
    }));
  };

  const getZoneScores = () => {
    return zones.map(zone => ({
      name: zone.quartier,
      score: parseFloat(zone.score_risque_moyen) || 0,
      niveau: zone.niveau_risque
    }));
  };

  const getAlertsTimeline = () => {
    const last7Days = {};
    for (let i = 6; i >= 0; i--) {
      const date = new Date();
      date.setDate(date.getDate() - i);
      const key = date.toISOString().split('T')[0];
      last7Days[key] = 0;
    }

    historicalData.forEach(alert => {
      const date = alert.timestamp.split('T')[0];
      if (date in last7Days) {
        last7Days[date]++;
      }
    });

    return Object.entries(last7Days).map(([date, count]) => ({
      date: new Date(date).toLocaleDateString('fr-FR', { month: 'short', day: 'numeric' }),
      alertes: count
    }));
  };

  if (loading) {
    return <div className="dashboard loading">Chargement des données...</div>;
  }

  return (
    <div className="predictions-dashboard">
      <header className="dashboard-header">
        <h1>📊 Dashboard Prédictions Inondations</h1>
        <p className="last-update">
          Dernière mise à jour: {lastUpdate?.toLocaleTimeString('fr-FR')}
        </p>
      </header>

      <div className="dashboard-grid">
        {/* Statistiques générales */}
        <section className="stats-section">
          <h2>État des Zones</h2>
          <div className="stats-container">
            {getRiskStats().map((stat, idx) => (
              <div key={idx} className="stat-card" style={{ borderLeftColor: stat.color }}>
                <div className="stat-label">{stat.name}</div>
                <div className="stat-value" style={{ color: stat.color }}>
                  {stat.value} zone{stat.value > 1 ? 's' : ''}
                </div>
              </div>
            ))}
          </div>
        </section>

        {/* Graphique des scores */}
        <section className="chart-section">
          <h2>Scores de Risque par Zone</h2>
          <ResponsiveContainer width="100%" height={300}>
            <BarChart data={getZoneScores()}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="name" angle={-45} textAnchor="end" height={100} />
              <YAxis domain={[0, 1]} />
              <Tooltip formatter={(value) => `${(value * 100).toFixed(0)}%`} />
              <Bar dataKey="score" radius={[8, 8, 0, 0]}>
                {getZoneScores().map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={COLORS[entry.niveau]} />
                ))}
              </Bar>
            </BarChart>
          </ResponsiveContainer>
        </section>

        {/* Historique des alertes */}
        <section className="chart-section">
          <h2>Alertes (7 derniers jours)</h2>
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={getAlertsTimeline()}>
              <CartesianGrid strokeDasharray="3 3" />
              <XAxis dataKey="date" />
              <YAxis />
              <Tooltip />
              <Line type="monotone" dataKey="alertes" stroke="#dc3545" strokeWidth={2} dot={{ r: 5 }} />
            </LineChart>
          </ResponsiveContainer>
        </section>

        {/* Distribution des risques */}
        <section className="chart-section">
          <h2>Distribution des Niveaux</h2>
          <ResponsiveContainer width="100%" height={300}>
            <PieChart>
              <Pie
                data={getRiskStats()}
                cx="50%"
                cy="50%"
                labelLine={false}
                label={({ name, value }) => `${name}: ${value}`}
                outerRadius={80}
                fill="#8884d8"
                dataKey="value"
              >
                {getRiskStats().map((entry, index) => (
                  <Cell key={`cell-${index}`} fill={entry.color} />
                ))}
              </Pie>
              <Tooltip />
            </PieChart>
          </ResponsiveContainer>
        </section>

        {/* Données météo */}
        {weatherData && (
          <section className="weather-section">
            <h2>🌤️ Conditions Météo</h2>
            <div className="weather-grid">
              <div className="weather-card">
                <span className="weather-label">Pluie 24h</span>
                <span className="weather-value">{weatherData.precipitation_mm}mm</span>
              </div>
              <div className="weather-card">
                <span className="weather-label">Température</span>
                <span className="weather-value">{weatherData.temperature_c}°C</span>
              </div>
              <div className="weather-card">
                <span className="weather-label">Humidité</span>
                <span className="weather-value">{weatherData.humidity_percent}%</span>
              </div>
              <div className="weather-card">
                <span className="weather-label">Source</span>
                <span className="weather-value">{weatherData.source}</span>
              </div>
            </div>
          </section>
        )}

        {/* Tableau des zones */}
        <section className="zones-section full-width">
          <h2>Détail des Zones</h2>
          <table className="zones-table">
            <thead>
              <tr>
                <th>Zone</th>
                <th>Niveau Risque</th>
                <th>Score</th>
                <th>Seuil Jaune</th>
                <th>Seuil Orange</th>
                <th>Seuil Rouge</th>
              </tr>
            </thead>
            <tbody>
              {zones.map(zone => (
                <tr key={zone.id} className={`level-${zone.niveau_risque}`}>
                  <td>{zone.quartier}</td>
                  <td>
                    <span className={`badge level-${zone.niveau_risque}`}>
                      {LEVEL_LABELS[zone.niveau_risque]}
                    </span>
                  </td>
                  <td>{(parseFloat(zone.score_risque_moyen) * 100).toFixed(1)}%</td>
                  <td>{(parseFloat(zone.seuil_jaune) * 100).toFixed(0)}%</td>
                  <td>{(parseFloat(zone.seuil_orange) * 100).toFixed(0)}%</td>
                  <td>{(parseFloat(zone.seuil_rouge) * 100).toFixed(0)}%</td>
                </tr>
              ))}
            </tbody>
          </table>
        </section>
      </div>
    </div>
  );
}

import { AlertTriangle, X } from 'lucide-react';

/**
 * Composant de confirmation pour actions destructrices
 * Accessible avec ARIA et keyboard navigation
 */
export default function ConfirmDialog({
  isOpen,
  title = "Confirmer l'action",
  message,
  confirmText = "Confirmer",
  cancelText = "Annuler",
  isDangerous = false,
  onConfirm,
  onCancel,
  isLoading = false
}) {
  if (!isOpen) return null;

  const handleBackdropClick = (e) => {
    if (e.target === e.currentTarget) onCancel();
  };

  return (
    <div
      role="presentation"
      className="fixed inset-0 bg-black/50 flex items-center justify-center z-50 p-4"
      onClick={handleBackdropClick}
    >
      <div
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="dialog-title"
        aria-describedby="dialog-message"
        className="bg-white dark:bg-navy-900 rounded-lg p-6 max-w-sm w-full shadow-xl border border-navy-100 dark:border-navy-700"
      >
        <div className="flex items-start gap-3 mb-4">
          {isDangerous && (
            <AlertTriangle
              size={24}
              className="text-orange-600 flex-shrink-0 mt-0.5"
              aria-hidden="true"
            />
          )}
          <h2
            id="dialog-title"
            className="text-lg font-bold text-navy-900 dark:text-white"
          >
            {title}
          </h2>
        </div>

        <p
          id="dialog-message"
          className="text-sm text-navy-600 dark:text-navy-200 mb-6"
        >
          {message}
        </p>

        <div className="flex gap-3 justify-end">
          <button
            onClick={onCancel}
            disabled={isLoading}
            className="px-4 py-2.5 rounded-md border border-navy-200 dark:border-navy-700 text-navy-900 dark:text-white font-semibold text-sm hover:bg-navy-50 dark:hover:bg-navy-800 transition disabled:opacity-60"
          >
            {cancelText}
          </button>
          <button
            onClick={onConfirm}
            disabled={isLoading}
            aria-busy={isLoading}
            className={`px-4 py-2.5 rounded-md font-semibold text-sm text-white transition disabled:opacity-60 ${
              isDangerous
                ? 'bg-orange-600 hover:bg-orange-700'
                : 'bg-red hover:bg-red-700'
            }`}
          >
            {isLoading ? 'Veuillez patienter...' : confirmText}
          </button>
        </div>
      </div>
    </div>
  );
}

import { AlertCircle, CheckCircle2 } from 'lucide-react';

/**
 * Composant de champ de formulaire avec validation inline
 * Affiche feedback en temps réel
 */
export default function FormField({
  id,
  label,
  description,
  value,
  error,
  isValid = null,
  type = 'text',
  placeholder,
  onChange,
  onBlur,
  required = false,
  validator = null,
  ...props
}) {
  // Validation inline en temps réel
  const hasError = error || (validator && value && !validator(value));
  const showValid = isValid === true || (validator && value && validator(value));

  return (
    <label className="block">
      <div className="flex items-center justify-between mb-1.5">
        <span className="block text-sm font-semibold text-navy-900 dark:text-white" id={`${id}-label`}>
          {label}
          {required && <span className="text-red ml-1" aria-label="requis">*</span>}
        </span>
        {showValid && (
          <span className="flex items-center gap-1 text-xs text-green-600 dark:text-green-400">
            <CheckCircle2 size={14} aria-hidden="true" />
            Valide
          </span>
        )}
      </div>

      {description && (
        <span
          className="block text-xs text-navy-500 dark:text-navy-400 mb-1.5"
          id={`${id}-desc`}
        >
          {description}
        </span>
      )}

      {type === 'textarea' ? (
        <textarea
          id={id}
          value={value}
          onChange={onChange}
          onBlur={onBlur}
          placeholder={placeholder}
          aria-labelledby={`${id}-label`}
          aria-describedby={description ? `${id}-desc` : undefined}
          aria-invalid={hasError}
          className={`w-full px-3.5 py-2.5 rounded-md border-[1.5px] transition ${
            hasError
              ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20'
              : showValid
              ? 'border-green-300 dark:border-green-700 bg-green-50 dark:bg-green-900/20'
              : 'border-navy-200 dark:border-navy-800 bg-white dark:bg-navy'
          } text-sm focus:ring-2 focus:ring-inset ${
            hasError ? 'focus:ring-red' : 'focus:ring-green-600'
          } focus:border-transparent`}
          {...props}
        />
      ) : (
        <input
          id={id}
          type={type}
          value={value}
          onChange={onChange}
          onBlur={onBlur}
          placeholder={placeholder}
          aria-labelledby={`${id}-label`}
          aria-describedby={description ? `${id}-desc` : undefined}
          aria-invalid={hasError}
          className={`w-full px-3.5 py-2.5 rounded-md border-[1.5px] transition ${
            hasError
              ? 'border-red-300 dark:border-red-700 bg-red-50 dark:bg-red-900/20'
              : showValid
              ? 'border-green-300 dark:border-green-700 bg-green-50 dark:bg-green-900/20'
              : 'border-navy-200 dark:border-navy-800 bg-white dark:bg-navy'
          } text-sm focus:ring-2 focus:ring-inset ${
            hasError ? 'focus:ring-red' : 'focus:ring-green-600'
          } focus:border-transparent`}
          {...props}
        />
      )}

      {hasError && (
        <div className="flex items-start gap-2 mt-1.5">
          <AlertCircle
            size={16}
            className="text-red-600 dark:text-red-400 flex-shrink-0 mt-0.5"
            aria-hidden="true"
          />
          <span
            role="alert"
            className="text-xs text-red-600 dark:text-red-400"
          >
            {error}
          </span>
        </div>
      )}
    </label>
  );
}

import { useEffect, useState } from 'react';
import { X, Bell, AlertTriangle, MessageSquare, Smartphone, CheckCircle, AlertCircle } from 'lucide-react';
import { useWebSocketNotifications } from '../hooks/useWebSocketNotifications';
import { useNotifications } from '../contexts/NotificationContext';

const NOTIFICATION_COLORS = {
  alerte: { bg: 'bg-red-50 dark:bg-red/15', border: 'border-red-200 dark:border-red-800', icon: AlertTriangle, color: 'text-red-600 dark:text-red-400' },
  signalement: { bg: 'bg-blue-50 dark:bg-blue/15', border: 'border-blue-200 dark:border-blue-800', icon: MessageSquare, color: 'text-blue-600 dark:text-blue-400' },
  sms: { bg: 'bg-purple-50 dark:bg-purple/15', border: 'border-purple-200 dark:border-purple-800', icon: Smartphone, color: 'text-purple-600 dark:text-purple-400' },
  prediction: { bg: 'bg-orange-50 dark:bg-orange/15', border: 'border-orange-200 dark:border-orange-800', icon: AlertTriangle, color: 'text-orange-600 dark:text-orange-400' },
  toast: { bg: 'bg-green-50 dark:bg-green/15', border: 'border-green-200 dark:border-green-800', icon: CheckCircle, color: 'text-green-600 dark:text-green-400' },
  error: { bg: 'bg-red-50 dark:bg-red/15', border: 'border-red-200 dark:border-red-800', icon: AlertCircle, color: 'text-red-600 dark:text-red-400' },
};

/**
 * Centre de notifications temps réel.
 * Affiche les notifications WebSocket + Toast (alertes, signalements, SMS, messages d'application).
 */
export default function NotificationCenter() {
  const { isConnected } = useWebSocketNotifications();
  const { notifications } = useNotifications();
  const [visibleNotifications, setVisibleNotifications] = useState([]);
  const [unreadCount, setUnreadCount] = useState(0);
  const [isOpen, setIsOpen] = useState(false);

  // Les notifications incluent à la fois les WebSocket et les Toast (déjà fusionnées dans le contexte)
  const allNotifications = notifications;

  // Ajouter les nouvelles notifications et les retirer après 10s
  useEffect(() => {
    if (allNotifications.length > 0) {
      const latestNotif = allNotifications[0];

      // Ajouter à la file d'affichage
      setVisibleNotifications((prev) => [latestNotif, ...prev].slice(0, 5));
      setUnreadCount((prev) => prev + 1);

      // Retirer automatiquement après 10 secondes (sauf si sélectionné)
      const timer = setTimeout(() => {
        setVisibleNotifications((prev) => prev.filter((n) => n.id !== latestNotif.id));
      }, 10000);

      return () => clearTimeout(timer);
    }
  }, [notifications]);

  const handleClose = (id) => {
    setVisibleNotifications((prev) => prev.filter((n) => n.id !== id));
  };

  const handleOpenPanel = () => {
    setIsOpen(!isOpen);
    if (!isOpen) {
      setUnreadCount(0);
    }
  };

  const getNotificationIcon = (type) => {
    const config = NOTIFICATION_COLORS[type] || NOTIFICATION_COLORS.alerte;
    const Icon = config.icon;
    return <Icon size={18} className={config.color} />;
  };

  return (
    <>
      {/* Notifications pop-up (coin haut droit) */}
      <div className="fixed top-4 right-4 z-[2000] space-y-2 pointer-events-none">
        {visibleNotifications.map((notif) => {
          const config = NOTIFICATION_COLORS[notif.type] || NOTIFICATION_COLORS.alerte;
          return (
            <div
              key={notif.id}
              className={`${config.bg} ${config.border} border rounded-lg p-3 shadow-lg pointer-events-auto flex gap-3 max-w-sm animate-slide-in-right`}
            >
              <div className="flex-shrink-0 pt-0.5">
                {getNotificationIcon(notif.type)}
              </div>
              <div className="flex-1 min-w-0">
                <p className="font-semibold text-sm text-gray-900 dark:text-gray-50">
                  {notif.data?.titre || notif.type}
                </p>
                <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5 line-clamp-2">
                  {notif.data?.message || notif.data?.description}
                </p>
                <p className="text-[10px] text-gray-500 dark:text-gray-500 mt-1">
                  {new Date(notif.timestamp).toLocaleTimeString()}
                </p>
              </div>
              <button
                onClick={() => handleClose(notif.id)}
                className="flex-shrink-0 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300"
              >
                <X size={16} />
              </button>
            </div>
          );
        })}
      </div>

      {/* Badge de notification (header) */}
      <div className="relative">
        <button
          onClick={handleOpenPanel}
          className="relative p-2 text-gray-600 dark:text-gray-300 hover:text-gray-900 dark:hover:text-gray-50 transition-colors"
          title={isConnected ? 'Notifications (connecté)' : 'Notifications (déconnecté)'}
        >
          <Bell size={20} />

          {/* Badge de compteur */}
          {unreadCount > 0 && (
            <span className="absolute top-0 right-0 inline-flex items-center justify-center px-2 py-1 text-xs font-bold leading-none text-white transform translate-x-1/2 -translate-y-1/2 bg-red-600 rounded-full animate-pulse-notification">
              {unreadCount > 9 ? '9+' : unreadCount}
            </span>
          )}

          {/* Indicateur de connexion */}
          <span
            className={`absolute bottom-0 right-0 w-2.5 h-2.5 rounded-full border border-white dark:border-gray-900 ${
              isConnected ? 'bg-green-500' : 'bg-gray-400'
            }`}
            title={isConnected ? 'Connecté' : 'Déconnecté'}
          />
        </button>

        {/* Panneau des notifications */}
        {isOpen && (
          <div className="absolute right-0 top-full mt-2 w-96 bg-white dark:bg-navy border border-gray-200 dark:border-navy-700 rounded-lg shadow-xl z-[2001]">
            <div className="flex items-center justify-between p-4 border-b border-gray-200 dark:border-navy-700">
              <h3 className="font-bold text-gray-900 dark:text-gray-50">Notifications</h3>
              <button
                onClick={() => setIsOpen(false)}
                className="text-gray-500 hover:text-gray-700 dark:hover:text-gray-300"
              >
                <X size={18} />
              </button>
            </div>

            {/* Liste des notifications */}
            <div className="max-h-96 overflow-y-auto">
              {allNotifications.length === 0 ? (
                <p className="p-4 text-center text-sm text-gray-500 dark:text-gray-400">
                  Aucune notification
                </p>
              ) : (
                <div className="divide-y divide-gray-200 dark:divide-navy-700">
                  {allNotifications.slice(0, 10).map((notif) => {
                    const config = NOTIFICATION_COLORS[notif.type] || NOTIFICATION_COLORS.alerte;
                    return (
                      <div key={notif.id} className="p-3 hover:bg-gray-50 dark:hover:bg-navy-800 cursor-pointer">
                        <div className="flex gap-2">
                          <div className="flex-shrink-0 pt-0.5">
                            {getNotificationIcon(notif.type)}
                          </div>
                          <div className="flex-1 min-w-0">
                            <p className="font-semibold text-sm text-gray-900 dark:text-gray-50">
                              {notif.data?.titre || notif.type}
                            </p>
                            <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5 line-clamp-2">
                              {notif.data?.message || notif.data?.description}
                            </p>
                            <p className="text-[10px] text-gray-500 dark:text-gray-500 mt-1">
                              {new Date(notif.timestamp).toLocaleTimeString()}
                            </p>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </div>

            {/* Statut de connexion */}
            <div className="border-t border-gray-200 dark:border-navy-700 p-2 text-xs text-gray-500 dark:text-gray-400">
              {isConnected ? (
                <span className="flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 bg-green-500 rounded-full" />
                  Connecté aux notifications temps réel
                </span>
              ) : (
                <span className="flex items-center gap-1.5">
                  <span className="w-1.5 h-1.5 bg-gray-400 rounded-full" />
                  En tentative de reconnexion...
                </span>
              )}
            </div>
          </div>
        )}
      </div>

      <style>{`
        @keyframes slide-in-right {
          from {
            transform: translateX(400px);
            opacity: 0;
          }
          to {
            transform: translateX(0);
            opacity: 1;
          }
        }
        .animate-slide-in-right {
          animation: slide-in-right 0.3s ease-out;
        }
        @keyframes pulse-notification {
          0%, 100% {
            box-shadow: 0 0 0 0 rgba(220, 38, 38, 0.7);
          }
          50% {
            box-shadow: 0 0 0 8px rgba(220, 38, 38, 0);
          }
        }
        .animate-pulse-notification {
          animation: pulse-notification 2s infinite;
        }
      `}</style>
    </>
  );
}

import { useEffect, useState } from 'react';
import { MapContainer, TileLayer, Polygon, Polyline, CircleMarker, Popup, useMap } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import { Layers, X } from 'lucide-react';
import { riskInfo } from '../RiskBadge';
import { polygonToLatLngs, lineToLatLngs, pointToLatLng } from './geoUtils';

// Centre de Thiaroye-sur-Mer — même point que celui utilisé côté backend
// pour le geofencing des signalements (SignalementCitoyenSerializer).
const THIAROYE_CENTER = [14.75, -17.38];

const LAYER_LABELS = {
  zones: 'Zones à risque',
  inondations: 'Zones inondées (historique)',
  segments: 'Rues & drainage',
  capteurs: 'Capteurs',
  signalements: 'Signalements citoyens',
  refuges: 'Points de refuge',
};

function formatDate(iso) {
  if (!iso) return '—';
  return new Date(iso).toLocaleDateString('fr-FR', { day: '2-digit', month: 'short', year: 'numeric' });
}

function segmentColor(score) {
  const value = Number(score ?? 0);
  if (value >= 0.6) return '#C0182A';
  if (value >= 0.3) return '#E0792E';
  return '#4A6480';
}

// Recentre/zoome automatiquement sur l'itinéraire dès qu'il apparaît (ou
// change) — sans ça il pourrait se retrouver hors du cadrage initial de la
// carte, centré sur Thiaroye-sur-Mer.
function FitRoute({ coordinates }) {
  const map = useMap();
  useEffect(() => {
    if (!coordinates?.length) return;
    map.fitBounds(
      coordinates.map(([lon, lat]) => [lat, lon]),
      { padding: [48, 48] }
    );
  }, [coordinates, map]);
  return null;
}

/**
 * Carte SIG partagée citoyen/autorité. Chaque couche n'apparaît (et n'est
 * proposée dans le sélecteur) que si la donnée correspondante est fournie —
 * ça permet à la page citoyenne de n'afficher que zones/inondations/signalements
 * pendant que l'autorité obtient la vue complète avec capteurs et segments.
 *
 * @param {object} data — { zones, inondations, segments, capteurs } en FeatureCollection GeoJSON, signalements en tableau de Feature.
 * @param {object} [route] — itinéraire à superposer, au format { type: 'LineString', coordinates: [[lon, lat], ...] } (voir useItineraireSecurise).
 */
export default function InteractiveMap({ data = {}, height = 560, route }) {
  const { zones, inondations, segments, capteurs, signalements, refuges } = data;

  const availableLayers = Object.keys(LAYER_LABELS).filter((key) => {
    if (key === 'signalements') return !!signalements?.length;
    return !!data[key]?.features?.length;
  });

  const [visible, setVisible] = useState(() =>
    availableLayers.reduce((acc, key) => ({ ...acc, [key]: true }), {})
  );
  // Replié par défaut et placé à droite (le zoom natif de Leaflet occupe le
  // coin haut-gauche) pour ne jamais se superposer aux popups de couche.
  const [panelOpen, setPanelOpen] = useState(false);

  const toggle = (key) => setVisible((v) => ({ ...v, [key]: !v[key] }));

  return (
    <div className="relative rounded-xl overflow-hidden border border-navy-50 dark:border-navy-800" style={{ height }}>
      {availableLayers.length > 0 && (
        // Ancré en bas à droite (et non en haut) — les popups Leaflet
        // s'ouvrent au-dessus du point cliqué, donc ce coin est celui qui a
        // le moins de chances de se superposer à un popup ouvert.
        <div className="absolute bottom-3 right-3 z-[1000] flex flex-col-reverse items-end gap-2">
          <button
            type="button"
            onClick={() => setPanelOpen((v) => !v)}
            className="w-9 h-9 rounded-lg bg-white/95 dark:bg-navy/95 backdrop-blur border border-navy-50 dark:border-navy-800 shadow-lg flex items-center justify-center text-navy dark:text-navy-50"
            aria-label="Afficher les couches de la carte"
          >
            {panelOpen ? <X size={16} /> : <Layers size={16} />}
          </button>
          {panelOpen && (
            <div className="bg-white/95 dark:bg-navy/95 backdrop-blur rounded-lg border border-navy-50 dark:border-navy-800 shadow-lg px-3 py-2.5 flex flex-col gap-1.5 max-w-[210px]">
              <div className="text-[11px] font-bold uppercase text-navy-400 mb-0.5">Couches</div>
              {availableLayers.map((key) => (
                <label key={key} className="flex items-center gap-2 text-xs text-navy dark:text-navy-50 cursor-pointer">
                  <input
                    type="checkbox"
                    checked={!!visible[key]}
                    onChange={() => toggle(key)}
                    className="accent-red"
                  />
                  {LAYER_LABELS[key]}
                </label>
              ))}
            </div>
          )}
        </div>
      )}

      <MapContainer center={THIAROYE_CENTER} zoom={15} scrollWheelZoom dragging touchZoom style={{ width: '100%', height: '100%' }}>
        <TileLayer
          attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors'
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {visible.zones &&
          zones.features.map((f) => {
            const { hex, label } = riskInfo(f.properties.niveau_risque);
            return (
              <Polygon
                key={`zone-${f.id}`}
                positions={polygonToLatLngs(f.geometry)}
                pathOptions={{ color: hex, fillColor: hex, fillOpacity: 0.3, weight: 2 }}
              >
                <Popup>
                  <div className="text-xs space-y-1 min-w-[160px]">
                    <div className="font-bold text-sm">{f.properties.quartier}</div>
                    <div>
                      Risque : <span className="font-semibold">{label}</span>
                    </div>
                    <div>Score moyen : {f.properties.score_risque_moyen}</div>
                    {f.properties.description && <p className="text-navy-600">{f.properties.description}</p>}
                  </div>
                </Popup>
              </Polygon>
            );
          })}

        {visible.inondations &&
          inondations.features.map((f) => (
            <Polygon
              key={`inondation-${f.id}`}
              positions={polygonToLatLngs(f.geometry)}
              pathOptions={{ color: '#4A6480', fillColor: '#4A6480', fillOpacity: 0.25, weight: 1, dashArray: '4,4' }}
            >
              <Popup>
                <div className="text-xs space-y-1 min-w-[160px]">
                  <div className="font-bold text-sm">Épisode d'inondation</div>
                  <div>Début : {formatDate(f.properties.date_debut)}</div>
                  <div>Fin : {f.properties.date_fin ? formatDate(f.properties.date_fin) : 'En cours'}</div>
                  {f.properties.surface_ha != null && <div>Surface : {f.properties.surface_ha} ha</div>}
                </div>
              </Popup>
            </Polygon>
          ))}

        {visible.segments &&
          segments.features.map((f) => (
            <Polyline
              key={`segment-${f.id}`}
              positions={lineToLatLngs(f.geometry)}
              pathOptions={{ color: segmentColor(f.properties.score_risque_actuel), weight: 4 }}
            >
              <Popup>
                <div className="text-xs space-y-1 min-w-[160px]">
                  <div className="font-bold text-sm">{f.properties.nom || 'Rue sans nom'}</div>
                  <div>Drainage : {f.properties.etat_drainage}</div>
                  <div>Score de risque : {f.properties.score_risque_actuel}</div>
                </div>
              </Popup>
            </Polyline>
          ))}

        {visible.capteurs &&
          capteurs.features.map((f) => {
            const point = pointToLatLng(f.geometry);
            if (!point) return null;
            return (
              <CircleMarker
                key={`capteur-${f.id}`}
                center={point}
                radius={7}
                pathOptions={{
                  color: '#fff',
                  weight: 2,
                  fillColor: f.properties.actif ? '#3C9A5F' : '#8AA0B8',
                  fillOpacity: 1,
                }}
              >
                <Popup>
                  <div className="text-xs space-y-1 min-w-[160px]">
                    <div className="font-bold text-sm">{f.properties.nom}</div>
                    <div>Type : {f.properties.type}</div>
                    <div>Statut : {f.properties.statut}</div>
                    {f.properties.dernier_releve && <div>Dernier relevé : {formatDate(f.properties.dernier_releve)}</div>}
                  </div>
                </Popup>
              </CircleMarker>
            );
          })}

        {visible.refuges &&
          refuges.features.map((f) => {
            const point = pointToLatLng(f.geometry);
            if (!point) return null;
            const typeColors = {
              ecole: '#3C9A5F',
              mosquee: '#8B5CF6',
              centre_sante: '#EF4444',
              mairie: '#F59E0B',
              bâtiment_public: '#06B6D4',
              autre: '#8AA0B8',
            };
            const typeLabel = {
              ecole: 'École',
              mosquee: 'Mosquée',
              centre_sante: 'Centre de santé',
              mairie: 'Mairie',
              bâtiment_public: 'Bâtiment public',
              autre: 'Autre',
            };
            const color = typeColors[f.properties.type_refuge] || '#8AA0B8';
            return (
              <CircleMarker
                key={`refuge-${f.id}`}
                center={point}
                radius={9}
                pathOptions={{
                  color: '#fff',
                  weight: 2,
                  fillColor: color,
                  fillOpacity: 1,
                }}
              >
                <Popup>
                  <div className="text-xs space-y-1 min-w-[200px]">
                    <div className="font-bold text-sm">{f.properties.nom}</div>
                    <div>Type : {typeLabel[f.properties.type_refuge]}</div>
                    <div>Quartier : {f.properties.quartier}</div>
                    {f.properties.adresse && <div>Adresse : {f.properties.adresse}</div>}
                    {f.properties.capacite && <div>Capacite : {f.properties.capacite} personnes</div>}
                    {f.properties.contact && <div>Contact : {f.properties.contact}</div>}
                    {f.properties.notes && <p className="text-navy-600 dark:text-navy-200 text-[11px] mt-1">{f.properties.notes}</p>}
                  </div>
                </Popup>
              </CircleMarker>
            );
          })}

        {visible.signalements &&
          signalements.map((f) => {
            const point = pointToLatLng(f.geometry);
            if (!point) return null;
            return (
              <CircleMarker
                key={`signalement-${f.id}`}
                center={point}
                radius={8}
                pathOptions={{
                  color: '#fff',
                  weight: 2,
                  fillColor: f.properties.valide ? '#C0182A' : '#8AA0B8',
                  fillOpacity: 1,
                }}
              >
                <Popup>
                  <div className="text-xs space-y-1 min-w-[180px] max-w-[220px]">
                    <div className="font-bold text-sm capitalize">{f.properties.categorie}</div>
                    <p className="text-navy-600 dark:text-navy-200">{f.properties.description}</p>
                    <div className="text-[10px] text-navy-400">
                      {f.properties.valide ? 'Validé' : 'En attente de validation'}
                    </div>
                  </div>
                </Popup>
              </CircleMarker>
            );
          })}

        {route?.coordinates?.length > 0 && (
          <>
            <Polyline
              positions={route.coordinates.map(([lon, lat]) => [lat, lon])}
              pathOptions={{ color: '#0D9488', weight: 7, opacity: 0.3 }}
            />
            <Polyline
              positions={route.coordinates.map(([lon, lat]) => [lat, lon])}
              pathOptions={{ color: '#0D9488', weight: 4, dashArray: '2,10', lineCap: 'round' }}
            />
            <CircleMarker
              center={[route.coordinates[0][1], route.coordinates[0][0]]}
              radius={7}
              pathOptions={{ color: '#fff', weight: 2, fillColor: '#1B2A40', fillOpacity: 1 }}
            >
              <Popup>Départ</Popup>
            </CircleMarker>
            <CircleMarker
              center={[route.coordinates.at(-1)[1], route.coordinates.at(-1)[0]]}
              radius={8}
              pathOptions={{ color: '#fff', weight: 2, fillColor: '#0D9488', fillOpacity: 1 }}
            >
              <Popup>Point sûr le plus proche</Popup>
            </CircleMarker>
            <FitRoute coordinates={route.coordinates} />
          </>
        )}
      </MapContainer>
    </div>
  );
}

