import { useEffect, useState } from 'react';

// Détection de breakpoint côté JS — nécessaire pour choisir quel shell
// monter (mobile vs desktop) sans jamais instancier les deux en même temps
// (ce qui dupliquerait les hooks de données et les effets de chaque page).
export function useMediaQuery(query) {
  const [matches, setMatches] = useState(() =>
    typeof window !== 'undefined' ? window.matchMedia(query).matches : false
  );

  useEffect(() => {
    const mql = window.matchMedia(query);
    const handler = (e) => setMatches(e.matches);
    setMatches(mql.matches);
    mql.addEventListener('change', handler);
    return () => mql.removeEventListener('change', handler);
  }, [query]);

  return matches;
}

import { useEffect, useState } from 'react';
import { useAuth } from '../../auth/AuthContext';
import { useNotifications } from '../contexts/NotificationContext';

/**
 * Hook pour recevoir les notifications push temps réel via WebSocket.
 * Gère la connexion WebSocket et expose les notifications reçues.
 *
 * Usage:
 * const { isConnected, notifications, lastNotification } = useWebSocketNotifications();
 */
export function useWebSocketNotifications() {
  const { token } = useAuth();
  const { addNotification } = useNotifications();
  const [isConnected, setIsConnected] = useState(false);
  const [notifications, setNotifications] = useState([]);
  const [lastNotification, setLastNotification] = useState(null);
  const [error, setError] = useState(null);

  useEffect(() => {
    if (!token) return;

    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const wsUrl = `${protocol}//${window.location.host}/ws/alertes/?token=${token}`;

    const ws = new WebSocket(wsUrl);

    // Connexion établie
    ws.onopen = () => {
      if (import.meta.env.DEV) console.log('[WebSocket] Connecté aux notifications');
      setIsConnected(true);
      setError(null);

      // Envoyer un heartbeat tous les 30 secondes
      const heartbeat = setInterval(() => {
        if (ws.readyState === WebSocket.OPEN) {
          ws.send(JSON.stringify({ type: 'ping' }));
        }
      }, 30000);

      ws.onclose = () => clearInterval(heartbeat);
    };

    // Message reçu
    ws.onmessage = (event) => {
      try {
        const payload = JSON.parse(event.data);

        // Ignorer les pongs
        if (payload.type === 'pong') return;

        // Ajouter à la liste des notifications
        const notification = {
          id: Math.random(),
          timestamp: new Date(),
          ...payload,
        };

        setNotifications((prev) => [notification, ...prev].slice(0, 100)); // Garder les 100 dernières
        setLastNotification(notification);

        // Ajouter aussi au système global de notifications
        addNotification(notification);

        // Afficher un toast/son si souhaité
        if (payload.type === 'alerte') {
          if (import.meta.env.DEV) console.warn('[WebSocket] Alerte reçue:', payload.data);
          // Peut déclencher une notification navigateur ici
          showBrowserNotification(payload.data.niveau, `Alerte ${payload.data.zone?.quartier || ''}`);
        } else if (payload.type === 'signalement') {
          if (import.meta.env.DEV) console.log('[WebSocket] Signalement reçu:', payload.data);
        } else if (payload.type === 'sms') {
          if (import.meta.env.DEV) console.log('[WebSocket] SMS reçu:', payload.data);
        }
      } catch (err) {
        if (import.meta.env.DEV) console.error('[WebSocket] Erreur parsing message:', err);
      }
    };

    // Erreur
    ws.onerror = (err) => {
      if (import.meta.env.DEV) console.error('[WebSocket] Erreur:', err);
      setError('Erreur connexion WebSocket');
      setIsConnected(false);
    };

    // Déconnexion
    ws.onclose = () => {
      if (import.meta.env.DEV) console.log('[WebSocket] Déconnecté');
      setIsConnected(false);
    };

    // Cleanup
    return () => {
      if (ws.readyState === WebSocket.OPEN) {
        ws.close();
      }
    };
  }, [token, addNotification]);

  return {
    isConnected,
    notifications,
    lastNotification,
    error,
  };
}

/**
 * Affiche une notification navigateur (Web Notifications API).
 */
function showBrowserNotification(niveau, titre) {
  if (!('Notification' in window)) {
    return;
  }

  if (Notification.permission === 'granted') {
    new Notification(titre, {
      icon: '/logo.png',
      badge: `/badge-${niveau}.png`,
      tag: 'alert',
      requireInteraction: niveau === 'rouge',
    });
  } else if (Notification.permission !== 'denied') {
    // Demander la permission
    Notification.requestPermission().then((permission) => {
      if (permission === 'granted') {
        new Notification(titre);
      }
    });
  }
}

import { useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import logoDark from '../../assets/logo-dark.png';

export default function SplashScreen() {
  const navigate = useNavigate();

  useEffect(() => {
    const timer = setTimeout(() => navigate('/login', { replace: true }), 1800);
    return () => clearTimeout(timer);
  }, [navigate]);

  return (
    <div
      onClick={() => navigate('/login', { replace: true })}
      className="min-h-screen bg-navy flex flex-col items-center justify-center gap-4 cursor-pointer"
    >
      <img src={logoDark} alt="MBEUND MI" className="h-10" />
      <div className="flex items-center gap-3">
        <span className="w-6 h-px bg-navy-50" />
        <span className="text-xs font-semibold tracking-widest uppercase text-navy-50">Bul Xaar, Waajal Ko.</span>
        <span className="w-6 h-px bg-navy-50" />
      </div>
      <span className="mt-2.5 text-xs font-bold tracking-wider uppercase text-navy-400">
        Plateforme de prévention des inondations
      </span>
      <div className="mt-10 flex gap-2">
        {[0, 1, 2].map((i) => (
          <span
            key={i}
            className="w-2 h-2 rounded-full bg-navy-50 animate-pulse"
            style={{ animationDelay: `${i * 0.15}s` }}
          />
        ))}
      </div>
    </div>
  );
}
